-- =====================================================================
-- CONSULTA A — tablas mapeadas que NO existen en la base. Esperado: 0 filas
-- (en produccion, hasta que se corra su DDL, ACCN y DACC son las esperadas).
-- =====================================================================
SELECT e.OWNER_ESP AS ESQUEMA, e.TABLA_ESP AS TABLA, 'TABLA NO EXISTE' AS PROBLEMA
FROM   ESPERADO e
WHERE  NOT EXISTS (SELECT 1 FROM ALL_TABLES t
                   WHERE t.OWNER = e.OWNER_ESP AND t.TABLE_NAME = e.TABLA_ESP)
ORDER  BY 1, 2;

