UNION ALL SELECT 'CRD', 'VGCN', 'CNTRCDGO,TPAPCDGO,VGCNCDGO,VGCNFCFN,VGCNFCIN,VGCNFCRG,VGCNIDHS,VGCNIDST,VGCNMNTO,VGCNMODO,VGCNOBSR,VGCNPRCN,VGCNRMUN,VGCNUSRG' FROM DUAL
),
EXPANDIDO AS (
    SELECT e.OWNER_ESP, e.TABLA_ESP,
           TRIM(REGEXP_SUBSTR(e.COLS, '[^,]+', 1, l.LVL)) AS COLUMNA_ESP
    FROM   ESPERADO e
    JOIN   (SELECT LEVEL AS LVL FROM DUAL CONNECT BY LEVEL <= 200) l
      ON   l.LVL <= REGEXP_COUNT(e.COLS, ',') + 1
)
SELECT x.OWNER_ESP AS ESQUEMA, x.TABLA_ESP AS TABLA, x.COLUMNA_ESP AS COLUMNA,
       'COLUMNA MAPEADA QUE NO EXISTE' AS PROBLEMA
FROM   EXPANDIDO x
WHERE  EXISTS (SELECT 1 FROM ALL_TABLES t
               WHERE t.OWNER = x.OWNER_ESP AND t.TABLE_NAME = x.TABLA_ESP)
AND    NOT EXISTS (SELECT 1 FROM ALL_TAB_COLUMNS c
                   WHERE c.OWNER = x.OWNER_ESP
                     AND c.TABLE_NAME = x.TABLA_ESP
                     AND c.COLUMN_NAME = x.COLUMNA_ESP)
ORDER  BY 1, 2, 3;
